From 378f79cab12b669928f3a4037f023837ead2ce0c Mon Sep 17 00:00:00 2001
From: Dan Carpenter <dan.carpenter@oracle.com>
Date: Sat, 30 Sep 2017 11:15:52 +0300
Subject: [PATCH] misc: pci_endpoint_test: Prevent some integer overflows

"size + max" can have an arithmetic overflow when we're allocating:

	orig_src_addr = dma_alloc_coherent(dev, size + alignment, ...

I've added a few checks to prevent that.

Fixes: 13107c60681f ("misc: pci_endpoint_test: Add support to provide aligned buffer addresses")
Signed-off-by: Dan Carpenter <dan.carpenter@oracle.com>
Signed-off-by: Greg Kroah-Hartman <gregkh@linuxfoundation.org>

diff --git a/drivers/misc/pci_endpoint_test.c b/drivers/misc/pci_endpoint_test.c
index deb203026496..c0d323077ad0 100644
--- a/drivers/misc/pci_endpoint_test.c
+++ b/drivers/misc/pci_endpoint_test.c
@@ -226,6 +226,9 @@ static bool pci_endpoint_test_copy(struct pci_endpoint_test *test, size_t size)
 	u32 src_crc32;
 	u32 dst_crc32;

+	if (size > SIZE_MAX - alignment)
+		goto err;
+
 	orig_src_addr = dma_alloc_coherent(dev, size + alignment,
 					   &orig_src_phys_addr, GFP_KERNEL);
 	if (!orig_src_addr) {
@@ -311,6 +314,9 @@ static bool pci_endpoint_test_write(struct pci_endpoint_test *test, size_t size)
 	size_t alignment = test->alignment;
 	u32 crc32;

+	if (size > SIZE_MAX - alignment)
+		goto err;
+
 	orig_addr = dma_alloc_coherent(dev, size + alignment, &orig_phys_addr,
 				       GFP_KERNEL);
 	if (!orig_addr) {
@@ -369,6 +375,9 @@ static bool pci_endpoint_test_read(struct pci_endpoint_test *test, size_t size)
 	size_t alignment = test->alignment;
 	u32 crc32;

+	if (size > SIZE_MAX - alignment)
+		goto err;
+
 	orig_addr = dma_alloc_coherent(dev, size + alignment, &orig_phys_addr,
 				       GFP_KERNEL);
 	if (!orig_addr) {
-- 
2.25.1

        You will be given the root cause of a bug, the commit message and the corresponding patch.
        You need to extract all code statements that lead to the bug from the patch, based on the root cause and the commit message.

        Root cause:
        The root cause of the bug is the potential for an integer overflow when calculating the total memory size required for allocation in functions that use `dma_alloc_coherent`. Specifically, when adding `size` and `alignment`, if `size` is too large, it may exceed `SIZE_MAX`, leading to incorrect memory allocation and potentially causing undefined behavior or crashes.

        Commit message:
        misc: pci_endpoint_test: Prevent some integer overflows

"size + max" can have an arithmetic overflow when we're allocating:

	orig_src_addr = dma_alloc_coherent(dev, size + alignment, ...

I've added a few checks to prevent that.

Fixes: 13107c60681f ("misc: pci_endpoint_test: Add support to provide aligned buffer addresses")
Signed-off-by: Dan Carpenter <dan.carpenter@oracle.com>
Signed-off-by: Greg Kroah-Hartman <gregkh@linuxfoundation.org>  

        Patch:

 static bool pci_endpoint_test_copy(struct pci_endpoint_test *test, size_t size)
 {
 	bool ret = false;
 	void *src_addr;
 	void *dst_addr;
 	dma_addr_t src_phys_addr;
 	dma_addr_t dst_phys_addr;
 	struct pci_dev *pdev = test->pdev;
 	struct device *dev = &pdev->dev;
 	void *orig_src_addr;
 	dma_addr_t orig_src_phys_addr;
 	void *orig_dst_addr;
 	dma_addr_t orig_dst_phys_addr;
 	size_t offset;
 	size_t alignment = test->alignment;
 	u32 src_crc32;
 	u32 dst_crc32;

+	if (size > SIZE_MAX - alignment)
+		goto err;
+
 	orig_src_addr = dma_alloc_coherent(dev, size + alignment,
 					   &orig_src_phys_addr, GFP_KERNEL);
 	if (!orig_src_addr) {
 		dev_err(dev, "failed to allocate source buffer\n");
 		ret = false;
 		goto err;
 	}

 	if (alignment && !IS_ALIGNED(orig_src_phys_addr, alignment)) {
 		src_phys_addr = PTR_ALIGN(orig_src_phys_addr, alignment);
 		offset = src_phys_addr - orig_src_phys_addr;
 		src_addr = orig_src_addr + offset;
 	} else {
 		src_phys_addr = orig_src_phys_addr;
 		src_addr = orig_src_addr;
 	}

 	pci_endpoint_test_writel(test, PCI_ENDPOINT_TEST_LOWER_SRC_ADDR,
 				 lower_32_bits(src_phys_addr));

 	pci_endpoint_test_writel(test, PCI_ENDPOINT_TEST_UPPER_SRC_ADDR,
 				 upper_32_bits(src_phys_addr));

 	get_random_bytes(src_addr, size);
 	src_crc32 = crc32_le(~0, src_addr, size);

 	orig_dst_addr = dma_alloc_coherent(dev, size + alignment,
 					   &orig_dst_phys_addr, GFP_KERNEL);
 	if (!orig_dst_addr) {
 		dev_err(dev, "failed to allocate destination address\n");
 		ret = false;
 		goto err_orig_src_addr;
 	}

 	if (alignment && !IS_ALIGNED(orig_dst_phys_addr, alignment)) {
 		dst_phys_addr = PTR_ALIGN(orig_dst_phys_addr, alignment);
 		offset = dst_phys_addr - orig_dst_phys_addr;
 		dst_addr = orig_dst_addr + offset;
 	} else {
 		dst_phys_addr = orig_dst_phys_addr;
 		dst_addr = orig_dst_addr;
 	}

 	pci_endpoint_test_writel(test, PCI_ENDPOINT_TEST_LOWER_DST_ADDR,
 				 lower_32_bits(dst_phys_addr));
 	pci_endpoint_test_writel(test, PCI_ENDPOINT_TEST_UPPER_DST_ADDR,
 				 upper_32_bits(dst_phys_addr));

 	pci_endpoint_test_writel(test, PCI_ENDPOINT_TEST_SIZE,
 				 size);

 	pci_endpoint_test_writel(test, PCI_ENDPOINT_TEST_COMMAND,
 				 1 << MSI_NUMBER_SHIFT | COMMAND_COPY);

 	wait_for_completion(&test->irq_raised);

 	dst_crc32 = crc32_le(~0, dst_addr, size);
 	if (dst_crc32 == src_crc32)
 		ret = true;

 	dma_free_coherent(dev, size + alignment, orig_dst_addr,
 			  orig_dst_phys_addr);

 err_orig_src_addr:
 	dma_free_coherent(dev, size + alignment, orig_src_addr,
 			  orig_src_phys_addr);

 err:
 	return ret;
 }

 static bool pci_endpoint_test_write(struct pci_endpoint_test *test, size_t size)
 {
 	bool ret = false;
 	u32 reg;
 	void *addr;
 	dma_addr_t phys_addr;
 	struct pci_dev *pdev = test->pdev;
 	struct device *dev = &pdev->dev;
 	void *orig_addr;
 	dma_addr_t orig_phys_addr;
 	size_t offset;
 	size_t alignment = test->alignment;
 	u32 crc32;

+	if (size > SIZE_MAX - alignment)
+		goto err;
+
 	orig_addr = dma_alloc_coherent(dev, size + alignment, &orig_phys_addr,
 				       GFP_KERNEL);
 	if (!orig_addr) {
 		dev_err(dev, "failed to allocate address\n");
 		ret = false;
 		goto err;
 	}

 	if (alignment && !IS_ALIGNED(orig_phys_addr, alignment)) {
 		phys_addr =  PTR_ALIGN(orig_phys_addr, alignment);
 		offset = phys_addr - orig_phys_addr;
 		addr = orig_addr + offset;
 	} else {
 		phys_addr = orig_phys_addr;
 		addr = orig_addr;
 	}

 	get_random_bytes(addr, size);

 	crc32 = crc32_le(~0, addr, size);
 	pci_endpoint_test_writel(test, PCI_ENDPOINT_TEST_CHECKSUM,
 				 crc32);

 	pci_endpoint_test_writel(test, PCI_ENDPOINT_TEST_LOWER_SRC_ADDR,
 				 lower_32_bits(phys_addr));
 	pci_endpoint_test_writel(test, PCI_ENDPOINT_TEST_UPPER_SRC_ADDR,
 				 upper_32_bits(phys_addr));

 	pci_endpoint_test_writel(test, PCI_ENDPOINT_TEST_SIZE, size);

 	pci_endpoint_test_writel(test, PCI_ENDPOINT_TEST_COMMAND,
 				 1 << MSI_NUMBER_SHIFT | COMMAND_READ);

 	wait_for_completion(&test->irq_raised);

 	reg = pci_endpoint_test_readl(test, PCI_ENDPOINT_TEST_STATUS);
 	if (reg & STATUS_READ_SUCCESS)
 		ret = true;

 	dma_free_coherent(dev, size + alignment, orig_addr, orig_phys_addr);

 err:
 	return ret;
 }

 static bool pci_endpoint_test_read(struct pci_endpoint_test *test, size_t size)
 {
 	bool ret = false;
 	void *addr;
 	dma_addr_t phys_addr;
 	struct pci_dev *pdev = test->pdev;
 	struct device *dev = &pdev->dev;
 	void *orig_addr;
 	dma_addr_t orig_phys_addr;
 	size_t offset;
 	size_t alignment = test->alignment;
 	u32 crc32;

+	if (size > SIZE_MAX - alignment)
+		goto err;
+
 	orig_addr = dma_alloc_coherent(dev, size + alignment, &orig_phys_addr,
 				       GFP_KERNEL);
 	if (!orig_addr) {
 		dev_err(dev, "failed to allocate destination address\n");
 		ret = false;
 		goto err;
 	}

 	if (alignment && !IS_ALIGNED(orig_phys_addr, alignment)) {
 		phys_addr = PTR_ALIGN(orig_phys_addr, alignment);
 		offset = phys_addr - orig_phys_addr;
 		addr = orig_addr + offset;
 	} else {
 		phys_addr = orig_phys_addr;
 		addr = orig_addr;
 	}

 	pci_endpoint_test_writel(test, PCI_ENDPOINT_TEST_LOWER_DST_ADDR,
 				 lower_32_bits(phys_addr));
 	pci_endpoint_test_writel(test, PCI_ENDPOINT_TEST_UPPER_DST_ADDR,
 				 upper_32_bits(phys_addr));

 	pci_endpoint_test_writel(test, PCI_ENDPOINT_TEST_SIZE, size);

 	pci_endpoint_test_writel(test, PCI_ENDPOINT_TEST_COMMAND,
 				 1 << MSI_NUMBER_SHIFT | COMMAND_WRITE);

 	wait_for_completion(&test->irq_raised);

 	crc32 = crc32_le(~0, addr, size);
 	if (crc32 == pci_endpoint_test_readl(test, PCI_ENDPOINT_TEST_CHECKSUM))
 		ret = true;

 	dma_free_coherent(dev, size + alignment, orig_addr, orig_phys_addr);
 err:
 	return ret;
 }



